'use strict';
const $=id=>document.getElementById(id),cfg=window.CCAR_CONFIG||{},connected=!!(cfg.supabaseUrl&&cfg.supabaseAnonKey);
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(Number(n)||0);
const photoURL=path=>cfg.supabaseUrl+'/storage/v1/object/public/vehicle-photos/'+path.split('/').map(encodeURIComponent).join('/');
let vehicle=null,currentPhoto=0;

async function request(path){const response=await fetch(cfg.supabaseUrl+path,{headers:{apikey:cfg.supabaseAnonKey}});if(!response.ok)throw Error('Não foi possível carregar o veículo.');return response.json();}
function analyticsSession(){let id=localStorage.getItem('ccar-analytics-session');if(!id){id=crypto.randomUUID();localStorage.setItem('ccar-analytics-session',id);}return id;}
function track(eventType){if(!connected||!vehicle)return;fetch(cfg.supabaseUrl+'/rest/v1/rpc/track_vehicle_event',{method:'POST',headers:{apikey:cfg.supabaseAnonKey,'Content-Type':'application/json'},body:JSON.stringify({p_vehicle_id:vehicle.id,p_event_type:eventType,p_session_id:analyticsSession()})}).catch(()=>{});}
function contact(){if(!vehicle||!cfg.whatsapp)return;track('contact');const text=`Olá! Tenho interesse no ${vehicle.make} ${vehicle.model} ${vehicle.version||''}, ano ${vehicle.year}, anunciado por ${money(vehicle.price)} na C CAR.`;window.open('https://wa.me/'+cfg.whatsapp.replace(/\D/g,'')+'?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');}
function selectPhoto(index){currentPhoto=(index+vehicle.photos.length)%vehicle.photos.length;const src=photoURL(vehicle.photos[currentPhoto]);$('vehicleCover').src=src;$('vehicleBackdrop').src=src;$('vehicleCover').alt=`${vehicle.make} ${vehicle.model} · foto ${currentPhoto+1}`;$('photoCounter').textContent=(currentPhoto+1)+' / '+vehicle.photos.length;$('lightboxImage').src=src;$('lightboxCounter').textContent=(currentPhoto+1)+' / '+vehicle.photos.length;document.querySelectorAll('[data-photo]').forEach(button=>{const active=+button.dataset.photo===currentPhoto;button.classList.toggle('active',active);if(active){const strip=$('vehicleThumbnails');strip.scrollTo({left:Math.max(0,button.offsetLeft-strip.clientWidth/2+button.clientWidth/2),behavior:'smooth'});}});}
function navigatePhotos(direction){if(vehicle?.photos?.length>1)selectPhoto(currentPhoto+direction);}
function openLightbox(){if(!vehicle?.photos?.length)return;selectPhoto(currentPhoto);$('photoLightbox').showModal();}
function card(v){return `<a class="card" href="veiculo.html?id=${encodeURIComponent(v.id)}"><img src="${v.photos?.length?safe(photoURL(v.photos[0])):'assets/logo.png'}" loading="lazy" alt="${safe(v.make+' '+v.model)}"${v.photos?.length?'':' style="object-fit:contain;padding:40px"'}><div class="card-body"><span class="badge">${safe(v.category)} • ${safe(v.year)}</span><h3>${safe(v.make)} ${safe(v.model)}</h3><p>${safe(v.version)}</p><p>${Number(v.km).toLocaleString('pt-BR')} km · ${safe(v.transmission)} · ${safe(v.fuel)}</p><strong>${money(v.price)}</strong><div class="card-action">Ver veículo</div></div></a>`;}
async function renderRelated(){try{const rows=await request('/rest/v1/vehicles?status=eq.published&category=eq.'+encodeURIComponent(vehicle.category)+'&id=neq.'+encodeURIComponent(vehicle.id)+'&select=*&order=created_at.desc&limit=3');if(rows.length){$('relatedVehicles').innerHTML=rows.map(card).join('');$('relatedSection').hidden=false;}}catch(_){}}
function render(){document.title=vehicle.make+' '+vehicle.model+' | C CAR';$('breadcrumbVehicle').textContent=vehicle.make+' '+vehicle.model;$('vehicleCategory').textContent=vehicle.category+' · '+vehicle.year;$('vehicleName').textContent=vehicle.make+' '+vehicle.model;$('vehicleVersion').textContent=vehicle.version||'';$('vehiclePrice').textContent=money(vehicle.price);$('vehicleDescription').textContent=vehicle.description||'Consulte a equipe C CAR para conhecer todos os detalhes deste veículo.';$('vehicleSpecs').innerHTML=`<div><span>Ano</span><strong>${safe(vehicle.year)}</strong></div><div><span>Quilometragem</span><strong>${Number(vehicle.km).toLocaleString('pt-BR')} km</strong></div><div><span>Câmbio</span><strong>${safe(vehicle.transmission)}</strong></div><div><span>Combustível</span><strong>${safe(vehicle.fuel)}</strong></div>`;if(vehicle.photos?.length){$('vehicleThumbnails').innerHTML=vehicle.photos.map((path,index)=>`<button data-photo="${index}" aria-label="Ver foto ${index+1}"><img src="${safe(photoURL(path))}" alt="Foto ${index+1}"></button>`).join('');$('vehicleThumbnails').querySelectorAll('[data-photo]').forEach(button=>button.onclick=()=>selectPhoto(+button.dataset.photo));const single=vehicle.photos.length===1;$('previousPhoto').hidden=single;$('nextPhoto').hidden=single;$('lightboxPrevious').hidden=single;$('lightboxNext').hidden=single;selectPhoto(0);}else{$('vehicleCover').src='assets/logo.png';$('vehicleCover').style.padding='18%';$('vehicleBackdrop').hidden=true;$('photoCounter').hidden=true;$('previousPhoto').hidden=true;$('nextPhoto').hidden=true;$('expandPhoto').hidden=true;}$('vehicleLoading').hidden=true;$('vehicleContent').hidden=false;track('view');renderRelated();}
async function load(){const id=new URLSearchParams(location.search).get('id');if(!connected||!id||!/^[0-9a-f-]{36}$/i.test(id)){showNotFound();return;}try{const rows=await request('/rest/v1/vehicles?id=eq.'+encodeURIComponent(id)+'&status=eq.published&select=*');if(!rows?.length){showNotFound();return;}vehicle=rows[0];render();}catch(_){showNotFound();}}
function showNotFound(){$('vehicleLoading').hidden=true;$('vehicleContent').hidden=true;$('vehicleNotFound').hidden=false;}
$('pageContact').onclick=contact;$('pageContactTop').onclick=()=>vehicle?contact():location.href='index.html#atendimento';$('previousPhoto').onclick=()=>navigatePhotos(-1);$('nextPhoto').onclick=()=>navigatePhotos(1);$('lightboxPrevious').onclick=()=>navigatePhotos(-1);$('lightboxNext').onclick=()=>navigatePhotos(1);$('expandPhoto').onclick=openLightbox;$('vehicleCover').onclick=openLightbox;$('closeLightbox').onclick=()=>$('photoLightbox').close();$('photoLightbox').onclick=event=>{if(event.target===$('photoLightbox'))$('photoLightbox').close();};document.addEventListener('keydown',event=>{if(!$('photoLightbox').open)return;if(event.key==='ArrowLeft')navigatePhotos(-1);if(event.key==='ArrowRight')navigatePhotos(1);});let touchStartX=0;for(const target of [$('vehiclePhotoStage'),$('photoLightbox')]){target.addEventListener('touchstart',event=>{touchStartX=event.changedTouches[0].clientX;},{passive:true});target.addEventListener('touchend',event=>{const delta=event.changedTouches[0].clientX-touchStartX;if(Math.abs(delta)>45)navigatePhotos(delta>0?-1:1);},{passive:true});}$('vehicleYearFooter').textContent=new Date().getFullYear();load();
